using BrewNest.Modules.Returns.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BrewNest.Modules.Returns.Infrastructure.EntityConfigurations;
internal static class Config{public static void Doc<T>(EntityTypeBuilder<T>b,string table)where T:ReturnDocument{b.ToTable(table);b.HasKey(x=>x.Id);b.Property(x=>x.Number).HasMaxLength(40);b.HasIndex(x=>x.Number).IsUnique();b.Property(x=>x.CreatedBy).HasMaxLength(200);b.Property(x=>x.ModifiedBy).HasMaxLength(200);b.Property(x=>x.RowVersion).IsRowVersion();}}
internal sealed class ReturnConfig:IEntityTypeConfiguration<ReturnRequest>{public void Configure(EntityTypeBuilder<ReturnRequest>b){Config.Doc(b,"ReturnRequests");b.Property(x=>x.RmaNumber).HasMaxLength(40);b.HasIndex(x=>x.RmaNumber).IsUnique();b.Property(x=>x.OrderNumber).HasMaxLength(40);b.Property(x=>x.BillNumber).HasMaxLength(40);b.Property(x=>x.Reason).HasMaxLength(500);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.CreditNoteNumber).HasMaxLength(40);b.Property(x=>x.RefundReference).HasMaxLength(100);b.HasMany(x=>x.Lines).WithOne(x=>x.ReturnRequest).HasForeignKey(x=>x.ReturnRequestId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Approvals).WithOne(x=>x.ReturnRequest).HasForeignKey(x=>x.ReturnRequestId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class LineConfig:IEntityTypeConfiguration<ReturnRequestLine>{public void Configure(EntityTypeBuilder<ReturnRequestLine>b){b.ToTable("ReturnRequestLines");b.HasKey(x=>x.Id);b.Property(x=>x.ItemCode).HasMaxLength(80);b.Property(x=>x.ItemName).HasMaxLength(200);b.Property(x=>x.Quantity).HasPrecision(18,3);b.Property(x=>x.UnitPrice).HasPrecision(18,2);b.Property(x=>x.LotNumber).HasMaxLength(100);b.Property(x=>x.Disposition).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Inspector).HasMaxLength(200);b.Property(x=>x.Criterion).HasMaxLength(200);b.Property(x=>x.Result).HasMaxLength(500);b.Property(x=>x.Remarks).HasMaxLength(500);b.Property(x=>x.SupportingReference).HasMaxLength(500);b.Property(x=>x.RowVersion).IsRowVersion();}}
internal sealed class CreditConfig:IEntityTypeConfiguration<CreditNote>{public void Configure(EntityTypeBuilder<CreditNote>b){Config.Doc(b,"CreditNotes");b.Property(x=>x.Amount).HasPrecision(18,2);b.Property(x=>x.Reason).HasMaxLength(500);b.HasIndex(x=>x.ReturnRequestId).IsUnique();}}
internal sealed class VoidConfig:IEntityTypeConfiguration<VoidRequest>{public void Configure(EntityTypeBuilder<VoidRequest>b){Config.Doc(b,"VoidRequests");b.Property(x=>x.OrderNumber).HasMaxLength(40);b.Property(x=>x.BillNumber).HasMaxLength(40);b.Property(x=>x.Amount).HasPrecision(18,2);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Reason).HasMaxLength(500);b.Property(x=>x.RefundReference).HasMaxLength(100);b.HasMany(x=>x.Approvals).WithOne(x=>x.VoidRequest).HasForeignKey(x=>x.VoidRequestId).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ApprovalConfig:IEntityTypeConfiguration<ReturnApproval>{public void Configure(EntityTypeBuilder<ReturnApproval>b){b.ToTable("ApprovalDecisions");b.HasKey(x=>x.Id);b.Property(x=>x.RequiredRole).HasMaxLength(100);b.Property(x=>x.Decision).HasMaxLength(30);b.Property(x=>x.DecidedBy).HasMaxLength(200);b.Property(x=>x.Remarks).HasMaxLength(500);b.ToTable(t=>t.HasCheckConstraint("CK_ReturnApproval_OneOwner","([ReturnRequestId] IS NULL AND [VoidRequestId] IS NOT NULL) OR ([ReturnRequestId] IS NOT NULL AND [VoidRequestId] IS NULL)"));}}
internal sealed class HistoryConfig:IEntityTypeConfiguration<ReturnStatusHistory>{public void Configure(EntityTypeBuilder<ReturnStatusHistory>b){b.ToTable("StatusHistory");b.HasKey(x=>x.Id);b.Property(x=>x.DocumentType).HasMaxLength(50);b.Property(x=>x.PreviousStatus).HasMaxLength(30);b.Property(x=>x.NewStatus).HasMaxLength(30);b.Property(x=>x.Reason).HasMaxLength(500);b.Property(x=>x.ChangedBy).HasMaxLength(200);}}
